from taf.ul.bts_kpi_report_generator.generator.function_sorted import sorted_names_LNCEL


class HTMLTable(object):
    def __init__(self, parameters):
        """

        :param parameters:
        """
        self.__parameters = parameters
        self.__table = '''<html>
<head>

        <style type="text/css">
        <!--
        table {
            background-color: #F9FBFD;
color: #000000;
width: 440px;
border: 1px solid #D7E5F2;
        border-collapse: collapse;
        }

    td, th {
border: 1px solid #D7E5F2;
padding: 4px;
    }
    p {
        font-weight: bold;
    }

    -->
        </style>
        <body>\n'''

    @property
    def table(self):
        """

        :return:
        """
        return self.__table

    def start_end_time(self, start_time, end_time):
        """

        :param start_time:
        :param end_time:
        :return:
        """
        self.__table += 'Start: {}<br/>\n'.format(start_time.strftime('%Y-%m-%d %H:%M:%S'))
        self.__table += 'End: {}<br/>\n'.format(end_time.strftime('%Y-%m-%d %H:%M:%S'))

    def add_to_table(self, type_measurement):
        """

        :param type_measurement:
        :return:
        """
        self.__table += '<p> {} <p>\n'.format(type_measurement)
        self.__table += '<table>\n'
        self.__table += '<th>ID</th><th>NAME</th>\n'

    def add_dn_table(self, dn_type):
        """

        :param dn_type:
        :return:
        """
        for dn in sorted(dn_type, key=sorted_names_LNCEL(dn_type)):
            self.__table += '<th>{}</th>\n'.format(dn)

    def add_rows(self, parameter, dn_type, name_counter):
        """

        :param parameter:
        :param dn_type:
        :param name_counter:
        :return:
        """
        self.__table += '<tr><td>{}</td><td>{}</td>\n'.format(parameter, name_counter)
        for dn in sorted(dn_type, key=sorted_names_LNCEL(dn_type)):
            if dn in self.__parameters['[{}]'.format(parameter)]:
                self.__table += '<td>{}</td>\n'.format(self.__parameters['[{}]'.format(parameter)][dn])
        self.__table += '</tr>\n'

    def add_end_table_tag(self):
        """

        :return:
        """
        self.__table += '</table>\n'

    def add_end_file_tag(self):
        """

        :return:
        """
        self.__table += '</body></html>'
